import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { describe, it } from "node:test";
import type { Plugin, ResolvedConfig } from "vite";
import legacy from "../dist/index.js";
import { rewriteSvelteKitClientEntries } from "../dist/rewrite.js";

describe("legacy", () => {
	it("rejects full legacy chunks", () => {
		assert.throws(
			() => legacy({ renderLegacyChunks: true } as never),
			/renderLegacyChunks: true is not supported/,
		);
	});

	it("rejects legacy-only modern output", () => {
		assert.throws(
			() => legacy({ renderModernChunks: false } as never),
			/renderModernChunks: false is not supported/,
		);
	});

	it("rejects legacy-only options", () => {
		for (const optionName of [
			"targets",
			"polyfills",
			"additionalLegacyPolyfills",
			"externalSystemJS",
			"modernPolyfills",
		]) {
			assert.throws(
				() => legacy({ [optionName]: true } as never),
				new RegExp(`${optionName} is not supported`),
			);
		}
	});
});

describe("build lifecycle", () => {
	function run(environmentName?: string, ssr = false) {
		const fixtureDir = createClientBuild({
			manifest: splitManifest({
				polyfillFile: "_app/immutable/polyfills.js",
				startFile: "_app/immutable/entry/start.js",
				appFile: "_app/immutable/entry/app.js",
			}),
			files: {
				"_app/immutable/polyfills.js": "globalThis.polyfilled = true;",
				"_app/immutable/entry/start.js": "export const start = () => {};",
				"_app/immutable/entry/app.js": "export const app = {};",
			},
		});
		const root = fs.mkdtempSync(path.join(os.tmpdir(), "legacy-build-"));
		const clientOutDir = path.join(root, "output", "client");
		fs.mkdirSync(path.dirname(clientOutDir), { recursive: true });
		fs.renameSync(fixtureDir, clientOutDir);
		const plugin = legacy().at(-1) as Plugin;
		const config = {
			root,
			build: {
				ssr,
				outDir: ssr || environmentName ? "missing-server-output" : clientOutDir,
			},
		} as ResolvedConfig;
		// The client environment must supply the output path, even when the
		// shared config points at SSR output and says it is an SSR build.
		const environment = environmentName
			? {
					name: environmentName,
					config: { ...config, build: { ssr: false, outDir: clientOutDir } },
				}
			: undefined;
		const resolve = plugin.configResolved as (config: ResolvedConfig) => void;
		resolve(config);
		const writeBundle = plugin.writeBundle as unknown as (this: object) => void;
		writeBundle.call(environment ? { environment } : {});
		return read(clientOutDir, "_app/immutable/entry/start.js");
	}

	it("skips old Vite SSR builds without reading a client manifest", () => {
		assert.doesNotMatch(run(undefined, true), /legacy-polyfills/);
	});
	it("wraps old Vite client builds", () => {
		assert.match(run(), /legacy-polyfills/);
	});
	it("skips SSR and custom server environments despite shared client config", () => {
		for (const name of ["ssr", "prerender", "server"]) {
			assert.doesNotMatch(run(name), /legacy-polyfills/);
		}
	});
	it("wraps the client environment using its own output directory", () => {
		assert.match(run("client", true), /legacy-polyfills/);
	});
});

describe("rewriteSvelteKitClientEntries", () => {
	it("wraps split SvelteKit start and app entries with the modern polyfill import", () => {
		const clientOutDir = createClientBuild({
			manifest: splitManifest({
				polyfillFile: "_app/immutable/polyfills.abc.js",
				startFile: "_app/immutable/entry/start.def.js",
				appFile: "_app/immutable/entry/app.ghi.js",
			}),
			files: {
				"_app/immutable/polyfills.abc.js": "globalThis.__polyfilled = true;",
				"_app/immutable/entry/start.def.js": "export const start = () => {};",
				"_app/immutable/entry/app.ghi.js": "export const app = {};",
			},
		});

		const result = rewriteSvelteKitClientEntries({ clientOutDir });

		assert.deepEqual(result, {
			polyfillFile: "_app/immutable/polyfills.abc.js",
			runtimePolyfillFile: "legacy-polyfills.js",
			wrappedFiles: [
				"_app/immutable/entry/start.def.js",
				"_app/immutable/entry/app.ghi.js",
			],
		});
		assert.equal(
			read(clientOutDir, "_app/immutable/entry/start.def.js"),
			[
				"// Generated by vite-plugin-sveltekit-legacy",
				'import "../../../legacy-polyfills.js";',
				'export * from "./start.def.sveltekit-original.js";',
				"",
			].join("\n"),
		);
		assert.equal(
			read(
				clientOutDir,
				"_app/immutable/entry/start.def.sveltekit-original.js",
			),
			"export const start = () => {};",
		);
		assert.equal(
			read(clientOutDir, "_app/immutable/entry/app.ghi.js"),
			[
				"// Generated by vite-plugin-sveltekit-legacy",
				'import "../../../legacy-polyfills.js";',
				'export * from "./app.ghi.sveltekit-original.js";',
				"",
			].join("\n"),
		);
		assert.equal(
			read(clientOutDir, "legacy-polyfills.js"),
			"globalThis.__polyfilled = true;",
		);
	});

	it("wraps single-bundle SvelteKit start entries", () => {
		const clientOutDir = createClientBuild({
			manifest: {
				"vite/legacy-polyfills": {
					file: "_app/immutable/polyfills.abc.js",
					name: "polyfills",
					src: "vite/legacy-polyfills",
					isEntry: true,
				},
				"../../node_modules/@sveltejs/kit/src/runtime/client/bundle.js": {
					file: "_app/immutable/entry/start.def.js",
					name: "entry/start",
					isEntry: true,
				},
			},
			files: {
				"_app/immutable/polyfills.abc.js": "globalThis.__polyfilled = true;",
				"_app/immutable/entry/start.def.js": "export const start = () => {};",
			},
		});

		const result = rewriteSvelteKitClientEntries({ clientOutDir });

		assert.deepEqual(result.wrappedFiles, [
			"_app/immutable/entry/start.def.js",
		]);
		assert.match(
			read(clientOutDir, "_app/immutable/entry/start.def.js"),
			/legacy-polyfills\.js/,
		);
	});

	it("keeps wrapper imports stable when the emitted polyfill hash changes", () => {
		const clientOutDir = createClientBuild({
			manifest: splitManifest({
				polyfillFile: "_app/immutable/polyfills.first.js",
				startFile: "_app/immutable/entry/start.def.js",
				appFile: "_app/immutable/entry/app.ghi.js",
			}),
			files: {
				"_app/immutable/polyfills.first.js": "globalThis.__polyfilled = 1;",
				"_app/immutable/entry/start.def.js": "export const start = () => {};",
				"_app/immutable/entry/app.ghi.js": "export const app = {};",
			},
		});

		rewriteSvelteKitClientEntries({ clientOutDir });

		const startWrapper = read(
			clientOutDir,
			"_app/immutable/entry/start.def.js",
		);
		writeManifest(
			clientOutDir,
			splitManifest({
				polyfillFile: "_app/immutable/polyfills.second.js",
				startFile: "_app/immutable/entry/start.def.js",
				appFile: "_app/immutable/entry/app.ghi.js",
			}),
		);
		write(
			clientOutDir,
			"_app/immutable/polyfills.second.js",
			"globalThis.__polyfilled = 2;",
		);

		rewriteSvelteKitClientEntries({ clientOutDir });

		assert.equal(
			read(clientOutDir, "_app/immutable/entry/start.def.js"),
			startWrapper,
		);
		assert.equal(
			read(clientOutDir, "legacy-polyfills.js"),
			"globalThis.__polyfilled = 2;",
		);
	});

	it("renames source maps and updates the original entry source map comment", () => {
		const clientOutDir = createClientBuild({
			manifest: splitManifest({
				polyfillFile: "_app/immutable/polyfills.abc.js",
				startFile: "_app/immutable/entry/start.def.js",
				appFile: "_app/immutable/entry/app.ghi.js",
			}),
			files: {
				"_app/immutable/polyfills.abc.js": "globalThis.__polyfilled = true;",
				"_app/immutable/entry/start.def.js": [
					"export const start = () => {};",
					"//# sourceMappingURL=start.def.js.map",
				].join("\n"),
				"_app/immutable/entry/start.def.js.map": "{}",
				"_app/immutable/entry/app.ghi.js": "export const app = {};",
			},
		});

		rewriteSvelteKitClientEntries({ clientOutDir });

		assert.equal(
			read(
				clientOutDir,
				"_app/immutable/entry/start.def.sveltekit-original.js",
			),
			[
				"export const start = () => {};",
				"//# sourceMappingURL=start.def.sveltekit-original.js.map",
			].join("\n"),
		);
		assert.equal(
			read(
				clientOutDir,
				"_app/immutable/entry/start.def.sveltekit-original.js.map",
			),
			"{}",
		);
	});

	it("is idempotent when the wrapper already exists", () => {
		const clientOutDir = createClientBuild({
			manifest: splitManifest({
				polyfillFile: "_app/immutable/polyfills.abc.js",
				startFile: "_app/immutable/entry/start.def.js",
				appFile: "_app/immutable/entry/app.ghi.js",
			}),
			files: {
				"_app/immutable/polyfills.abc.js": "globalThis.__polyfilled = true;",
				"_app/immutable/entry/start.def.js": "export const start = () => {};",
				"_app/immutable/entry/app.ghi.js": "export const app = {};",
			},
		});

		rewriteSvelteKitClientEntries({ clientOutDir });
		assert.doesNotThrow(() => rewriteSvelteKitClientEntries({ clientOutDir }));
	});

	it("fails when vite/legacy-polyfills is missing by default", () => {
		const clientOutDir = createClientBuild({
			manifest: splitManifest({
				startFile: "_app/immutable/entry/start.def.js",
				appFile: "_app/immutable/entry/app.ghi.js",
			}),
			files: {
				"_app/immutable/entry/start.def.js": "export const start = () => {};",
				"_app/immutable/entry/app.ghi.js": "export const app = {};",
			},
		});

		assert.throws(
			() => rewriteSvelteKitClientEntries({ clientOutDir }),
			/did not emit vite\/legacy-polyfills/,
		);
	});

	it("no-ops when vite/legacy-polyfills is missing and failOnMissingPolyfills is false", () => {
		const clientOutDir = createClientBuild({
			manifest: splitManifest({
				startFile: "_app/immutable/entry/start.def.js",
				appFile: "_app/immutable/entry/app.ghi.js",
			}),
			files: {
				"_app/immutable/entry/start.def.js": "export const start = () => {};",
				"_app/immutable/entry/app.ghi.js": "export const app = {};",
			},
		});

		assert.deepEqual(
			rewriteSvelteKitClientEntries({
				clientOutDir,
				failOnMissingPolyfills: false,
			}),
			{
				polyfillFile: null,
				runtimePolyfillFile: null,
				wrappedFiles: [],
			},
		);
	});

	it("rejects legacy polyfill chunks", () => {
		const clientOutDir = createClientBuild({
			manifest: splitManifest({
				polyfillFile: "_app/immutable/polyfills-legacy.abc.js",
				startFile: "_app/immutable/entry/start.def.js",
				appFile: "_app/immutable/entry/app.ghi.js",
			}),
			files: {
				"_app/immutable/polyfills-legacy.abc.js": "System.import('x');",
				"_app/immutable/entry/start.def.js": "export const start = () => {};",
				"_app/immutable/entry/app.ghi.js": "export const app = {};",
			},
		});

		assert.throws(
			() => rewriteSvelteKitClientEntries({ clientOutDir }),
			/Full legacy nomodule output is not supported/,
		);
	});
});

function splitManifest(options: {
	polyfillFile?: string;
	startFile: string;
	appFile: string;
}) {
	return {
		...(options.polyfillFile
			? {
					"vite/legacy-polyfills": {
						file: options.polyfillFile,
						name: "polyfills",
						src: "vite/legacy-polyfills",
						isEntry: true,
					},
				}
			: {}),
		"../../node_modules/@sveltejs/kit/src/runtime/client/entry.js": {
			file: options.startFile,
			name: "entry/start",
			isEntry: true,
		},
		".svelte-kit/generated/client-optimized/app.js": {
			file: options.appFile,
			name: "entry/app",
			isEntry: true,
		},
	};
}

function createClientBuild(options: {
	manifest: object;
	files: Record<string, string>;
}) {
	const clientOutDir = fs.mkdtempSync(
		path.join(os.tmpdir(), "sveltekit-legacy-"),
	);
	const manifestPath = path.join(clientOutDir, ".vite", "manifest.json");

	fs.mkdirSync(path.dirname(manifestPath), { recursive: true });
	fs.writeFileSync(manifestPath, JSON.stringify(options.manifest, null, 2));

	for (const [file, contents] of Object.entries(options.files)) {
		const filePath = path.join(clientOutDir, file);
		fs.mkdirSync(path.dirname(filePath), { recursive: true });
		fs.writeFileSync(filePath, contents);
	}

	return clientOutDir;
}

function writeManifest(clientOutDir: string, manifest: object) {
	const manifestPath = path.join(clientOutDir, ".vite", "manifest.json");
	fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2));
}

function write(clientOutDir: string, file: string, contents: string) {
	const filePath = path.join(clientOutDir, file);
	fs.mkdirSync(path.dirname(filePath), { recursive: true });
	fs.writeFileSync(filePath, contents);
}

function read(clientOutDir: string, file: string) {
	return fs.readFileSync(path.join(clientOutDir, file), "utf8");
}
